mapper.select:
SELECT stp.id, stp.plan_name AS planName, stp.base_id AS baseId, stp.route, stp.brief_intro AS briefIntro, stp.details, stp.suitable_crowd AS suitableCrowd, stp.duration, stp.status, stp.create_time AS createTime, stp.update_time AS updateTime, COALESCE(( SELECT COUNT(*) FROM user_collect uc WHERE uc.target_type = 'study_plan' AND uc.target_id = CAST(stp.id AS CHAR) ), 0) AS collectNumber, CASE WHEN #{userId} IS NOT NULL AND EXISTS ( SELECT 1 FROM user_collect uc2 WHERE uc2.user_id = #{userId} AND uc2.target_type = 'study_plan' AND uc2.target_id = CAST(stp.id AS CHAR) ) THEN 1 ELSE 0 END AS isCollect FROM study_tour_plan stp
INNER JOIN study_tour_base stb ON stp.base_id = stb.id
AND stb.user_id = #{merchantUserId}
AND stp.plan_name LIKE CONCAT('%', #{planName}, '%')
AND stp.base_id = #{baseId}
AND stp.status = #{status}
ORDER BY stp.create_time DESC

